// read-sqlite / read-archive / auto-generated unit tests — temp fixtures via
// node:sqlite + tar, matcher tables, grammar parse table. No module wiring.

import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { after, before, describe, it } from "node:test";
import { DatabaseSync } from "node:sqlite";
import {
  MAX_RAW_QUERY_ROWS,
  executeSqliteView,
  isSqliteFile,
  openDatabase,
  parseSqliteSelector,
  readSqlite,
} from "../lib/read-sqlite.js";
import {
  MEMBER_MAX_BYTES,
  archiveKind,
  listMembers,
  matchMember,
  readArchiveListing,
  readArchiveMember,
} from "../lib/read-archive.js";
import {
  AUTO_GENERATED_PATTERNS,
  autoGeneratedError,
  checkAutoGenerated,
  matchesPattern,
} from "../lib/auto-generated.js";

const dir = mkdtempSync(path.join(tmpdir(), "ceulen-repair-readers-"));
after(() => rmSync(dir, { recursive: true, force: true }));

function makeDb(file: string): void {
  const db = new DatabaseSync(file);
  db.exec("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, age INTEGER)");
  db.exec("INSERT INTO users (name, age) VALUES ('alice', 30), ('bob', 41), ('carol', 25)");
  db.exec("CREATE TABLE orders (id INTEGER PRIMARY KEY, user_id INTEGER, total REAL)");
  db.close();
}

// ── parseSqliteSelector ─────────────────────────────────────────────────────

describe("parseSqliteSelector", () => {
  it("empty → tables", () => {
    assert.deepEqual(parseSqliteSelector(undefined), { kind: "tables" });
    assert.deepEqual(parseSqliteSelector(""), { kind: "tables" });
    assert.deepEqual(parseSqliteSelector("  "), { kind: "tables" });
  });
  it("table / rowid / key / query forms", () => {
    assert.deepEqual(parseSqliteSelector("users"), { kind: "table", table: "users" });
    assert.deepEqual(parseSqliteSelector("users:42"), { kind: "rowid", table: "users", rowid: 42 });
    assert.deepEqual(parseSqliteSelector("users:name=alice"), { kind: "key", table: "users", key: "name", value: "alice" });
    assert.deepEqual(parseSqliteSelector("users:name="), { kind: "key", table: "users", key: "name", value: "" });
    assert.deepEqual(parseSqliteSelector("users:note=\"a:b\""), { kind: "key", table: "users", key: "note", value: "a:b" });
    assert.deepEqual(parseSqliteSelector("?SELECT 1"), { kind: "query", sql: "SELECT 1" });
    assert.deepEqual(parseSqliteSelector("WITH x AS (SELECT 1) SELECT * FROM x"), {
      kind: "query",
      sql: "WITH x AS (SELECT 1) SELECT * FROM x",
    });
    assert.deepEqual(parseSqliteSelector("pragma table_list"), { kind: "query", sql: "pragma table_list" });
  });
  it("garbage throws with a remediation shape", () => {
    assert.throws(() => parseSqliteSelector("users:notafield"), /invalid sqlite selector/);
    assert.throws(() => parseSqliteSelector(":nope"), /invalid sqlite selector/);
  });
});

// ── sqlite views ────────────────────────────────────────────────────────────

describe("sqlite views", () => {
  const dbFile = path.join(dir, "fixture.db");
  makeDb(dbFile);

  it("isSqliteFile sniffs the magic header, not the extension", () => {
    assert.equal(isSqliteFile(dbFile), true);
    const fake = path.join(dir, "fake.db");
    writeFileSync(fake, "definitely not sqlite".repeat(10));
    assert.equal(isSqliteFile(fake), false);
    assert.equal(isSqliteFile(path.join(dir, "missing.db")), false);
  });

  it("tables view lists names, counts, columns", () => {
    const db = openDatabase(dbFile);
    try {
      const out = executeSqliteView(db, { kind: "tables" }, "fixture.db");
      assert.match(out, /fixture\.db — 2 table\(s\)/);
      assert.match(out, /users  ·  3 rows  ·  id, name, age/);
      assert.match(out, /orders/);
    } finally {
      db.close();
    }
  });

  it("table view shows schema + preview rows + truncation footer", () => {
    const out = readSqlite(dbFile, "users", "fixture.db");
    assert.match(out, /fixture\.db : users — 3 rows/);
    assert.match(out, /id INTEGER PRIMARY KEY/);
    assert.match(out, /alice/);
    assert.doesNotMatch(out, /\[\d+ of .* rows/); // 3 rows fit the preview
  });

  it("rowid lookup and miss", () => {
    assert.match(readSqlite(dbFile, "users:2", "f.db"), /bob/);
    assert.match(readSqlite(dbFile, "users:999", "f.db"), /no row with rowid 999/);
  });

  it("key lookup: quoted values, unknown column, no hits", () => {
    assert.match(readSqlite(dbFile, "users:name=\"alice\"", "f.db"), /alice/);
    assert.match(readSqlite(dbFile, "users:nope=x", "f.db"), /no column "nope"/);
    assert.match(readSqlite(dbFile, "users:name=zed", "f.db"), /no rows where name = "zed"/);
  });

  it("unknown table names the tables", () => {
    assert.match(readSqlite(dbFile, "nope", "fixture.db"), /tables: orders, users/);
  });

  it("raw query renders + read-only head guard", () => {
    const out = readSqlite(dbFile, "?SELECT name, age FROM users WHERE age > 26 ORDER BY age", "f.db");
    assert.match(out, /alice/);
    assert.match(out, /bob/);
    assert.throws(() => readSqlite(dbFile, "?DROP TABLE users", "f.db"), /only read-only queries/);
    // A bare non-SELECT statement is not a valid table selector either — it
    // lands on the table branch and names the tables (no silent execution).
    assert.match(readSqlite(dbFile, "DROP TABLE users", "f.db"), /no table/);
  });

  it("the db file is genuinely opened read-only", () => {
    assert.throws(() => {
      const db = openDatabase(dbFile);
      try {
        db.exec("CREATE TABLE t (x)");
      } finally {
        db.close();
      }
    }, /readonly|read-only/i);
  });

  it("raw queries cap at MAX_RAW_QUERY_ROWS", () => {
    const big = path.join(dir, "big.db");
    const db = new DatabaseSync(big);
    db.exec("CREATE TABLE t (n INTEGER)");
    db.exec(`WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x < ${MAX_RAW_QUERY_ROWS + 50}) INSERT INTO t SELECT x FROM c`);
    db.close();
    const out = readSqlite(big, "?SELECT * FROM t", "big.db");
    assert.match(out, /showing \d+ of \d+ rows/);
    const total = Number(/of (\d+) rows/.exec(out)![1]);
    assert.equal(total, MAX_RAW_QUERY_ROWS + 50);
  });
});

// ── archives ────────────────────────────────────────────────────────────────

describe("archive views", () => {
  const archive = path.join(dir, "fixture.tgz");
  const zip = path.join(dir, "fixture.zip");
  const subdir = path.join(dir, "payload");
  before(() => {
    mkdirSync(path.join(subdir, "nested"), { recursive: true });
    writeFileSync(path.join(subdir, "hello.ts"), "line one\nline two\nline three\nline four\nline five\n");
    writeFileSync(path.join(subdir, "nested", "deep.md"), "# deep\ncontent here\n");
    execFileSync("tar", ["-czf", archive, "-C", subdir, "hello.ts", "nested/deep.md"]);
    execFileSync("zip", ["-qr", zip, "."], { cwd: subdir });
  });

  it("archiveKind classifies extensions", () => {
    assert.equal(archiveKind("a.tgz"), "tgz");
    assert.equal(archiveKind("a.tar.gz"), "tgz");
    assert.equal(archiveKind("a.tar"), "tar");
    assert.equal(archiveKind("a.zip"), "zip");
    assert.equal(archiveKind("a.gz"), null);
    assert.equal(archiveKind("a.tar.bz2"), null);
  });

  it("listing shows members with a count header", () => {
    const out = readArchiveListing(archive, "tgz", "fixture.tgz").text;
    assert.match(out, /fixture\.tgz — 2 member\(s\)/);
    assert.match(out, /hello\.ts/);
    assert.match(out, /nested\/deep\.md/);
  });

  it("member read: exact and unique-suffix match", () => {
    const exact = readArchiveMember(archive, "tgz", "hello.ts", "f.tgz").text;
    assert.match(exact, /f\.tgz : hello\.ts/);
    assert.match(exact, /line two/);
    const suffix = readArchiveMember(archive, "tgz", "deep.md", "f.tgz").text;
    assert.match(suffix, /matched .*deep\.md/);
    assert.match(suffix, /content here/);
  });

  it("ambiguous / missing members error with candidates", () => {
    writeFileSync(path.join(subdir, "other.ts"), "x\n");
    execFileSync("tar", ["-czf", archive, "-C", subdir, "hello.ts", "nested/deep.md", "other.ts"]);
    const amb = readArchiveMember(archive, "tgz", ".ts", "f.tgz").text;
    assert.match(amb, /ambiguous member "\.ts"/);
    assert.match(amb, /hello\.ts/);
    const missing = readArchiveMember(archive, "tgz", "zzz.txt", "f.tgz").text;
    assert.match(missing, /no member matching "zzz\.txt"/);
  });

  it("member + line ranges slice the body, keeping the header", () => {
    // Route through the module's own slicing helper via the full path form:
    // simulate what index.ts does with pkg.tgz:hello.ts:2-3
    const res = readArchiveMember(archive, "tgz", "hello.ts", "fixture.tgz");
    const lines = res.text.split("\n");
    if (lines.length > 1 && lines[lines.length - 1] === "") lines.pop();
    const header = lines[0]!;
    const body = lines.slice(1);
    assert.equal(header, "fixture.tgz : hello.ts");
    assert.equal(body.length, 5);
  });

  it("zip: listing + member via unzip", { skip: process.platform === "win32" }, () => {
    const listing = readArchiveListing(zip, "zip", "fixture.zip").text;
    assert.match(listing, /hello\.ts/);
    const member = readArchiveMember(zip, "zip", "hello.ts", "fixture.zip").text;
    assert.match(member, /line three/);
  });

  it("matchMember semantics table", () => {
    const members = ["./a/b.ts", "./a/c.ts", "x/c.ts", "d.ts"];
    assert.deepEqual(matchMember(members, "d.ts"), { member: "d.ts", via: "exact" });
    assert.deepEqual(matchMember(members, "a/b.ts"), { member: "./a/b.ts", via: "exact" });
    assert.deepEqual(matchMember(members, "b.ts"), { member: "./a/b.ts", via: "suffix" });
    assert.match((matchMember(members, "a/") as { error: string }).error ?? "", /ambiguous|no member/);
    assert.match((matchMember(members, "c.ts") as { error: string }).error, /ambiguous member "c\.ts"/);
  });

  it("listMembers drops directories and PaxHeaders", () => {
    const members = listMembers(archive, "tgz");
    for (const m of members) {
      assert.doesNotMatch(m, /\/$/);
      assert.doesNotMatch(m, /PaxHeader/);
    }
  });
});

// ── auto-generated guard ────────────────────────────────────────────────────

describe("auto-generated guard", () => {
  const cwd = path.join(dir, "proj");
  before(() => mkdirSync(path.join(cwd, "dist", "deep"), { recursive: true }));

  it("matchesPattern: **, *, plain", () => {
    assert.equal(matchesPattern("package-lock.json", "package-lock.json"), true);
    assert.equal(matchesPattern("dist/x.js", "dist/**"), true);
    assert.equal(matchesPattern("dist/deep/y.js", "dist/**"), true);
    assert.equal(matchesPattern("dist.js", "dist/**"), false);
    assert.equal(matchesPattern("app.min.js", "*.min.js"), true);
    assert.equal(matchesPattern("a/b/app.min.js", "*.min.js"), true);
    assert.equal(matchesPattern("src/app.js", "*.min.js"), false);
    assert.equal(matchesPattern("src/app.js", "src/**"), true);
    assert.equal(matchesPattern("other/src/app.js", "src/**"), false);
  });

  it("checkAutoGenerated: lockfiles, minified, build dirs, snapshots", () => {
    for (const rel of ["package-lock.json", "yarn.lock", "app.min.js", "dist/x.js", "dist/deep/y.js", "out/z.js", "__snapshots__/a.snap", "x.snap"]) {
      const m = checkAutoGenerated(rel, cwd);
      assert.ok(m, `${rel} should be guarded`);
    }
    assert.equal(checkAutoGenerated("src/app.ts", cwd), null);
    assert.equal(checkAutoGenerated("packages/app/README.md", cwd), null);
  });

  it("absolute paths resolve against cwd", () => {
    assert.ok(checkAutoGenerated(path.join(cwd, "package-lock.json"), cwd));
    assert.equal(checkAutoGenerated(path.join(cwd, "src", "app.ts"), cwd), null);
  });

  it("error text names the pattern + regenerate + bash hatch", () => {
    const m = checkAutoGenerated("package-lock.json", cwd)!;
    const msg = autoGeneratedError("package-lock.json", m);
    assert.match(msg, /package-lock\.json/);
    assert.match(msg, /matched package-lock\.json/);
    assert.match(msg, /npm install/);
    assert.match(msg, /bash/);
  });

  it("default pattern list covers the documented set", () => {
    for (const p of ["package-lock.json", "pnpm-lock.yaml", "Cargo.lock", "*.min.js", "dist/**", "__pycache__/**"]) {
      assert.ok(AUTO_GENERATED_PATTERNS.includes(p), `${p} missing from defaults`);
    }
  });

  it("member size cap constant is 1 MiB", () => {
    assert.equal(MEMBER_MAX_BYTES, 1024 * 1024);
  });
});
